import {PERIODS,TIMES,DAYS,DEMO,courseSessions,conflicts,timeLabel,googleUrl,safeUrl,activeEntries,layoutEntries,taipeiNow,nextClass} from './model.js';
const ICONS={calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2Zm3 10h2m4 0h2m-8 3h2m4 0h2',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16',book:'M12 5C9 3 5 3 2 4v16c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1Zm0 0v16',info:'M12 8h.01M12 11v6M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',close:'m6 6 12 12M6 18 18 6',plus:'M12 5v14M5 12h14',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Zm-5 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',clock:'M12 6v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',navigate:'m21 3-6 18-4-8-8-4 18-6Z',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',search:'M21 21l-5-5m2-6a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',check:'m5 12 4 4L19 6',locate:'M12 2v3m0 14v3M2 12h3m14 0h3M19 12a7 7 0 1 1-14 0 7 7 0 0 1 14 0Zm-5 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',layers:'m12 2 10 6-10 6L2 8l10-6Zm-10 10 10 6 10-6M2 16l10 6 10-6',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',external:'M14 3h7v7m0-7L11 13M10 4H4v16h16v-6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[n]??ICONS.info}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const palette=[['#2c64c7','#eaf2ff'],['#087e7a','#e6f5f2'],['#8256ba','#f1ebfc'],['#b16a25','#fff3e4'],['#537596','#edf3f8'],['#b25679','#fbeaf1']];
let data,byId,state,view='schedule',mode=matchMedia('(max-width:700px)').matches?'day':'week',activeDay=taipeiNow().day,renderedMaps=[],toastTimer;
let browseQuery='',browseDept='all',browseOnly=false,mapQuery='',mapScope='selected',mapRoom=null,campusMap=null,mapMarkers=[];
const selected=()=>state.ids.map(id=>byId.get(id)).filter(Boolean);
const roomOf=s=>s.room?(data.rooms[s.room.key]??s.room):null;
const color=c=>{const i=state.ids.indexOf(c.id);return palette[(i>=0?i:c.id.split('').reduce((n,v)=>n+v.charCodeAt(0),0))%palette.length];};
const style=c=>`--course-color:${color(c)[0]};--course-bg:${color(c)[1]}`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function save(){try{localStorage.setItem('ncku-campus-demo-v1',JSON.stringify(state));}catch{toast('瀏覽器無法記住變更，目前仍可繼續操作。');}}
function loadState(){const fallback={ids:DEMO.filter(id=>byId.has(id)),tutorials:{},edited:false};try{const x=JSON.parse(localStorage.getItem('ncku-campus-demo-v1'));if(x&&Array.isArray(x.ids)&&x.ids.every(id=>typeof id==='string')&&x.tutorials&&typeof x.tutorials==='object'){return{ids:[...new Set(x.ids)].filter(id=>byId.has(id)),tutorials:Object.fromEntries(Object.entries(x.tutorials).filter(([id,v])=>Number.isInteger(v)&&v>=0&&v<(byId.get(id)?.tutorials.length??0))),edited:!!x.edited};}}catch{}return fallback;}
function disposeMaps(){renderedMaps.forEach(m=>m.remove());renderedMaps=[];campusMap=null;mapMarkers=[];}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function render(){disposeMaps();view=['schedule','map','courses'].includes(location.hash.slice(1))?location.hash.slice(1):'schedule';$$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===view);if(a.dataset.nav===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(view==='schedule')renderSchedule();else if(view==='courses')renderCourses();else renderMap();}
function scheduleStats(){const all=selected();const rooms=new Set(all.flatMap(c=>courseSessions(c,state.tutorials).map(s=>roomOf(s)?.bid).filter(Boolean)));return `<div class="stats-strip"><span class="stat"><b>${all.length}</b> 門課程</span><span class="stat"><b>${all.reduce((n,c)=>n+c.credits,0)}</b> 修課學分</span><span class="stat"><b>${rooms.size}</b> 座館舍</span><span class="demo-tag">${state.edited?'我的展示課表':'示範課表'}</span></div>`;}
function conflictNotice(){const c=conflicts(selected(),state.tutorials);return c.length?`<div class="conflict-banner" role="status"><strong>${c.length} 組課程時間重疊</strong> · ${c.map(x=>`${esc(byId.get(x.a).name)} / ${esc(byId.get(x.b).name)}（${x.days.map(d=>'週'+DAYS[d]).join('、')}）`).join('；')}。請調整課程，或保留作為比較。</div>`:'';}
function renderSchedule(){const all=selected();const next=nextClass(all,state.tutorials);const preview=next??(all.length?{course:all[0],session:all[0].sessions[0]}:null);
$('#main').innerHTML=heading('我的課表','從這一堂課，找到你的下一站。',`<a class="button" href="#courses">${icon('plus')}新增課程</a>`)+scheduleStats()+conflictNotice()+`<div class="schedule-layout"><section class="panel schedule-panel" aria-label="我的上課時間表"><div class="panel-header"><h2>115–1 學期課表</h2><div class="segmented" aria-label="課表顯示方式"><button data-mode="week" class="${mode==='week'?'active':''}" aria-pressed="${mode==='week'}">週課表</button><button data-mode="day" class="${mode==='day'?'active':''}" aria-pressed="${mode==='day'}">每日課程</button></div></div>${all.length?(mode==='week'?weekTable():dayAgenda()):`<div class="empty">${icon('calendar')}<h3>留一點空間，給新的學期</h3><p>從官方課程清單勾選你想修的課，<br>上課時間與教室會一起加入。</p><a href="#courses" class="button">探索課程</a></div>`}<div class="legend"><span><i style="background:#7aa7e8"></i>點選課程查看教室與導航</span><span>學分為修課規劃，非已取得學分</span></div></section><aside class="schedule-aside">${preview?`<section class="spotlight"><span class="eyebrow">${next?'下一堂 · 依每週課表':'課程位置'}</span><h2>${esc(preview.course.name)}</h2><div class="spot-meta">${icon('clock')}${preview.session?timeLabel(preview.session):'時間待公告'}</div><div class="spot-meta">${icon('pin')}${esc(roomOf(preview.session??{})?.label??'教室待公告')}</div><button class="button" data-detail="${preview.course.id}">${icon('navigate')}帶我去上課</button><small>固定週課表推算，不含停課或補課異動</small></section>`:''}<section class="panel"><div id="mini-map" class="mini-map" aria-label="課程館舍地圖"></div><div class="map-preview-footer"><h3>上課地點，一目了然</h3><p>找到館舍，再用官方樓層圖確認教室。</p><a class="button ghost" href="#map">${icon('map')}查看教室地圖</a></div></section><p class="aside-note">${all.some(c=>c.tutorials.length)?'微積分等課程有分組習課，請在課程詳情選擇分組。<br>':''}僅供課程規劃與展示，實際選課請至<br><a href="https://course.ncku.edu.tw/" target="_blank" rel="noopener">成大選課系統</a>。</p></aside></div>${unscheduledNotice()}`;
$('#main').querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render();});$('#main').querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{activeDay=Number(b.dataset.day);render();});bindDetails();initMiniMap();}
function weekTable(){const all=selected();const allSessions=all.flatMap(c=>courseSessions(c,state.tutorials));const days=Array.from({length:allSessions.some(s=>s.day>5)?7:5},(_,i)=>i+1);const used=allSessions.flatMap(s=>s.periods.map(p=>PERIODS.indexOf(p)));const first=Math.min(1,...used);const last=Math.max(9,...used);const shown=PERIODS.slice(first,last+1);let html=`<div class="timetable" style="--days:${days.length}"><div class="tt-corner"></div>${days.map(d=>`<div class="tt-day ${d===taipeiNow().day?'today':''}">週${DAYS[d]}</div>`).join('')}<div class="tt-times">${shown.map(p=>`<div class="tt-time"><b>${p}</b><span>${TIMES[p][0]}</span></div>`).join('')}</div>`;
for(const day of days){const entries=layoutEntries(activeEntries(all,state.tutorials,day));html+=`<div class="tt-column" style="height:${shown.length*65}px">`;for(const {course:c,session:s,lane,laneCount} of entries){const width=100/laneCount;const top=(PERIODS.indexOf(s.periods[0])-first)*65+4;const h=s.periods.length*65-8;html+=`<button class="tt-course ${s.periods.length===1?'short-slot':''}" data-detail="${c.id}" style="${style(c)};top:${top}px;height:${h}px;left:calc(${lane*width}% + 4px);width:calc(${width}% - 8px)" aria-label="${esc(c.name)}，${esc(timeLabel(s))}，${esc(roomOf(s)?.label??'教室待公告')}"><strong>${esc(c.name)}${s.tutorial?'・習課':''}</strong><span class="tt-room">${esc(roomOf(s)?.label??'教室待公告')}</span><span class="tt-code">${c.id}</span></button>`;}html+='</div>';}return html+'</div>';}
function dayAgenda(){const entries=activeEntries(selected(),state.tutorials,activeDay);return `<div class="day-picker">${Array.from({length:7},(_,i)=>i+1).map(d=>`<button data-day="${d}" class="${activeDay===d?'active':''}" aria-pressed="${activeDay===d}">週${DAYS[d]}<small>${activeEntries(selected(),state.tutorials,d).length} 堂</small></button>`).join('')}</div><div class="agenda-list">${entries.length?entries.map(({course:c,session:s})=>`<div class="agenda-item"><div class="agenda-time">${TIMES[s.periods[0]][0]}<small>${TIMES[s.periods.at(-1)][1]}</small></div><button class="agenda-card" data-detail="${c.id}" style="${style(c)}"><strong>${esc(c.name)}${s.tutorial?'・習課':''}</strong><span>${esc(roomOf(s)?.label??'教室待公告')} · ${c.credits} 學分</span></button></div>`).join(''):`<div class="empty">${icon('calendar')}<h3>週${DAYS[activeDay]}沒有排課</h3><p>切換其他日期查看課程，<br>或去探索這學期的新課。</p><a href="#courses" class="button secondary">新增課程</a></div>`}</div>`;}
function unscheduledNotice(){const pending=selected().filter(c=>!c.sessions.some(s=>s.day&&s.periods.length));return pending.length?`<section class="panel unscheduled"><h3>時間待公告的課程</h3>${pending.map(c=>`<button class="button secondary" data-detail="${c.id}">${esc(c.name)}</button>`).join('')}<p class="small muted">已計入課程與學分，尚未排入週課表。</p></section>`:'';}
function bindDetails(){$$('[data-detail]').forEach(b=>b.onclick=()=>openDetail(b.dataset.detail));}
function roomButtons(r){const g=googleUrl(r);const official=safeUrl(r?.url,['nckumap.ncku.edu.tw']);return `<div class="room-actions">${g?`<a href="${esc(g)}" target="_blank" rel="noopener" class="button">${icon('navigate')}步行導航</a>`:`<span class="muted small">館舍座標待確認</span>`}${official?`<a href="${esc(official)}" target="_blank" rel="noopener" class="button secondary">${icon('layers')}成大教室圖</a>`:`<a href="https://nckumap.ncku.edu.tw/map.php" target="_blank" rel="noopener" class="button secondary">查詢成大地圖</a>`}</div>`;}
function openDetail(id){const c=byId.get(id);if(!c)return;const sessions=courseSessions(c,state.tutorials);const rooms=[...new Map(sessions.filter(s=>s.room).map(s=>[s.room.key,roomOf(s)])).values()];const on=state.ids.includes(id);$('#detail-body').innerHTML=`<div class="detail-head"><div class="dialog-top"><span class="eyebrow">COURSE DETAILS · ${id}</span><button class="icon-button" data-close="detail-dialog" aria-label="關閉課程詳情">${icon('close')}</button></div><h2 id="detail-title">${esc(c.name)}</h2><div class="detail-tags"><span class="pill">${esc(c.departmentLabel)}</span><span class="pill">${c.credits} 學分</span><span class="pill">${esc(c.year||c.category)}</span></div></div><div class="detail-content"><div class="detail-row">${icon('user')}<div>${esc(c.teacher||'授課教師待公告')}<small>授課教師</small></div></div><div class="detail-row">${icon('clock')}<div>${sessions.filter(s=>s.day).map(s=>esc(timeLabel(s))+(s.tutorial?'（習課）':'')).join('<br>')||'上課時間待公告'}<small>依成大官方節次表</small></div></div>${c.tutorials.length?`<label class="tutorial-label">習課分組<select id="tutorial-select"><option value="">尚未選擇 · 請依教師分組</option>${c.tutorials.map((t,i)=>`<option value="${i}" ${state.tutorials[id]===i?'selected':''}>${esc(t.label)} · ${esc(t.sessions.map(s=>roomOf(s)?.label??'地點未定').join('、'))}</option>`).join('')}</select></label><p class="small muted">僅將選定分組加入課表；分組請以教師公告為準。</p>`:''}<h3>上課教室</h3>${rooms.length?rooms.map(r=>`<div class="room-card"><h3>${esc(r.label)}</h3><span class="small muted">${r.floor?esc(r.floor)+' · ':''}${r.lat?'館舍位置已確認':'位置待確認'}${!r.floor?' · 官方尚無樓層資訊':''}</span>${roomButtons(r)}${r.lat?`<button class="button ghost small-btn" data-map-room="${esc(r.key)}">在校園地圖查看</button>`:''}</div>`).join(''):`<div class="info-note">教室尚未公告，請留意學校課程系統與授課教師通知。</div>`}<p class="small muted">步行導航帶你到館舍；館內教室請查看成大教室圖。</p><button class="button ${on?'secondary':''} wide" id="detail-toggle">${icon(on?'check':'plus')}${on?'已加入課表 · 點選移除':'加入我的課表'}</button><div class="detail-notes">${esc(c.notes)}${c.syllabus?`<br><a href="${esc(safeUrl(c.syllabus,['class-qry.acad.ncku.edu.tw'])??'https://course.ncku.edu.tw/')}" target="_blank" rel="noopener">查看官方課程大綱</a>`:''}</div></div>`;bindClose();$('#detail-toggle').onclick=()=>{toggleCourse(id);openDetail(id);};$('#tutorial-select')?.addEventListener('change',e=>{if(e.target.value==='')delete state.tutorials[id];else state.tutorials[id]=Number(e.target.value);state.edited=true;save();render();openDetail(id);toast('已更新習課分組');});$$('[data-map-room]').forEach(b=>b.onclick=()=>{mapRoom=b.dataset.mapRoom;mapQuery='';if(!selected().some(c=>courseSessions(c,state.tutorials).some(s=>s.room?.key===mapRoom)))mapScope='all';$('#detail-dialog').close();if(location.hash==='#map')render();else location.hash='map';});if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}
function toggleCourse(id){if(!byId.has(id))return;const was=state.ids.includes(id);state.ids=was?state.ids.filter(x=>x!==id):[...state.ids,id];state.edited=true;save();render();const conflict=!was&&conflicts(selected(),state.tutorials).some(c=>c.a===id||c.b===id);toast(was?'已從課表移除':conflict?'已加入，但與其他課程時間重疊，請查看課表提醒。':'已加入課表');}
function makeMap(element,mini=false){if(!window.L){element.innerHTML='<div class="map-fallback">互動地圖暫時無法載入，仍可使用官方地圖與步行導航連結。</div>';return null;}const map=L.map(element,{zoomControl:!mini,scrollWheelZoom:!mini,dragging:!mini,touchZoom:!mini,doubleClickZoom:!mini,boxZoom:!mini,keyboard:!mini}).setView([22.9985,120.2197],16);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'}).on('tileerror',()=>{const hint=element.parentElement.querySelector('.map-status');if(hint)hint.hidden=false;}).addTo(map);renderedMaps.push(map);return map;}
function marker(map,room,n,active=false){return L.marker([room.lat,room.lng],{icon:L.divIcon({className:'campus-pin'+(active?' active':''),html:String(n),iconSize:[27,27],iconAnchor:[13,13]}),title:room.label}).addTo(map);}
function initMiniMap(){const map=makeMap($('#mini-map'),true);if(!map)return;const rooms=[...new Map(selected().flatMap(c=>courseSessions(c,state.tutorials)).map(roomOf).filter(r=>r?.lat).map(r=>[r.bid,r])).values()];rooms.forEach((r,i)=>marker(map,r,i+1));if(rooms.length)map.fitBounds(rooms.map(r=>[r.lat,r.lng]),{padding:[25,25],maxZoom:16});}
function bindClose(){$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());}
let browseLimit=30,browseYear='all';
function renderCourses(){$('#main').innerHTML=heading('探索課程','勾選想修的課，時間和教室一起加入課表。',`<a class="button secondary" href="#schedule">${icon('calendar')}查看課表 <span class="count-bubble">${state.ids.length}</span></a>`)+`<section class="catalog-controls"><label class="search-field">${icon('search')}<input id="course-search" type="search" placeholder="搜尋課名、教師、課號或教室" aria-label="搜尋課程" value="${esc(browseQuery)}"></label><div class="filter-chips" aria-label="課程類別">${[['all','全部課程'],...Object.entries(data.departments)].map(([key,label])=>`<button data-dept="${key}" class="chip ${key===browseDept?'active':''}" aria-pressed="${key===browseDept}">${esc(label)}</button>`).join('')}</div><div class="catalog-filter-row"><label class="checkbox-label"><input id="only-selected" type="checkbox" ${browseOnly?'checked':''}>只看已加入 <span class="muted">${state.ids.length}</span></label><label class="year-filter">年級 <select id="year-filter"><option value="all">所有年級</option>${[1,2,3,4].map(n=>`<option value="${n}" ${browseYear===String(n)?'selected':''}>${n} 年級</option>`).join('')}</select></label><button class="text-button danger" id="clear-courses">清空課表</button></div></section><div class="results-heading"><span id="result-count"></span><span class="muted">115–1 官方課程 · 10/02 更新</span></div><div id="course-results" class="course-grid"></div><div id="more-courses" class="load-more"></div><div class="catalog-note">${icon('info')}這裡的勾選只建立展示課表，不會向學校送出選課。各組必修與加簽限制請查看課程詳情。</div>`;
$('#course-search').oninput=e=>{browseQuery=e.target.value;browseLimit=30;renderCourseResults();};$$('[data-dept]').forEach(b=>b.onclick=()=>{browseDept=b.dataset.dept;browseLimit=30;renderCourses();});$('#only-selected').onchange=e=>{browseOnly=e.target.checked;browseLimit=30;renderCourseResults();};$('#year-filter').onchange=e=>{browseYear=e.target.value;browseLimit=30;renderCourseResults();};$('#clear-courses').onclick=()=>{if(!state.ids.length){toast('課表目前是空的');return;}if(confirm('清空目前勾選的全部課程？之後仍可重新加入。')){state.ids=[];state.edited=true;save();render();toast('課表已清空');}};renderCourseResults();}
function renderCourseResults(){const query=browseQuery.trim().toLocaleLowerCase();const list=data.courses.filter(c=>(browseDept==='all'||c.department===browseDept)&&(!browseOnly||state.ids.includes(c.id))&&(browseYear==='all'||c.year.startsWith(browseYear))&&(!query||[c.name,c.id,c.code,c.teacher,c.timeText,c.departmentLabel].join(' ').toLocaleLowerCase().includes(query)));$('#result-count').innerHTML=`找到 <strong>${list.length}</strong> 門課程`;const conflictPairs=conflicts(selected(),state.tutorials);$('#course-results').innerHTML=list.slice(0,browseLimit).map(c=>{const on=state.ids.includes(c.id);const overlap=on?conflictPairs.some(p=>p.a===c.id||p.b===c.id):conflicts([...selected(),c],state.tutorials).some(p=>p.a===c.id||p.b===c.id);const sessions=c.sessions.filter(s=>s.day);const rooms=[...new Set(c.sessions.map(s=>roomOf(s)?.label).filter(Boolean))];return `<article class="course-card ${on?'selected':''}"><div class="course-card-top"><span class="course-category">${esc(c.departmentLabel)} <span>· ${c.id}</span></span><label class="course-check"><input type="checkbox" data-toggle="${c.id}" ${on?'checked':''} aria-label="${on?'移除':'加入'}${esc(c.name)}"><span>${on?'已加入':'加入'}</span></label></div><button class="course-name" data-detail="${c.id}">${esc(c.name)}</button><div class="course-meta"><span>${c.credits} 學分</span><span>${esc(c.teacher||'教師待公告')}</span>${c.year?`<span>${esc(c.year)} 年級／班級</span>`:''}</div><div class="course-line">${icon('clock')}<span>${sessions.length?sessions.map(s=>timeLabel(s)).join('、'):'時間待公告'}</span></div><div class="course-line">${icon('pin')}<span>${esc(rooms.join('、')||'教室待公告')}</span></div><div class="course-card-bottom">${overlap?'<span class="badge-conflict">與已選課程時間重疊</span>':`<span class="small muted">${c.tutorials.length?'另有分組習課':esc(c.category==='講義'?'查看詳情與選課限制':c.category)}</span>`}<button class="text-button" data-detail="${c.id}">課程與教室</button></div></article>`;}).join('')||`<div class="empty full-span">${icon('search')}<h3>沒有找到符合的課程</h3><p>試試其他關鍵字，或調整課程類別和篩選。</p><button class="button secondary" id="reset-filters">清除搜尋與篩選</button></div>`;
$('#more-courses').innerHTML=list.length>browseLimit?`<button class="button secondary" id="load-more">顯示更多課程（還有 ${list.length-browseLimit} 門）</button>`:list.length?'<span class="small muted">已顯示全部符合的課程</span>':'';$('#load-more')?.addEventListener('click',()=>{browseLimit+=30;renderCourseResults();});$('#reset-filters')?.addEventListener('click',()=>{browseQuery='';browseDept='all';browseOnly=false;browseYear='all';renderCourses();});$$('[data-toggle]').forEach(input=>input.onchange=()=>toggleCourse(input.dataset.toggle));bindDetails();}
function filteredMapRooms(){let rooms=mapScope==='all'?Object.values(data.rooms):[...new Map(selected().flatMap(c=>courseSessions(c,state.tutorials)).map(roomOf).filter(Boolean).map(r=>[r.key,r])).values()];const q=mapQuery.trim().toLowerCase();return rooms.filter(r=>!q||[r.label,r.room,r.building,...selected().filter(c=>courseSessions(c,state.tutorials).some(s=>s.room?.key===r.key)).map(c=>c.name)].join(' ').toLowerCase().includes(q));}
function renderMap(){$('#main').innerHTML=heading('教室地圖','先找到館舍，再找到你的教室。',`<button id="locate-me" class="button secondary">${icon('locate')}我的位置</button>`)+`<div class="map-layout"><section class="map-surface panel"><div class="map-topline"><div class="segmented"><button data-map-scope="selected" class="${mapScope==='selected'?'active':''}" aria-pressed="${mapScope==='selected'}">我的課程</button><button data-map-scope="all" class="${mapScope==='all'?'active':''}" aria-pressed="${mapScope==='all'}">全部教室</button></div><button class="icon-button" id="fit-map" aria-label="顯示所有館舍">${icon('map')}</button></div><div id="campus-map" aria-label="可互動的成大教室地圖"></div><div class="map-status" hidden>底圖暫時無法完整載入。教室座標仍可選取，也可使用下方官方地圖與導航連結。</div><div class="map-caption">${icon('pin')}圖釘標示館舍中心點；不是館舍入口</div></section><aside class="map-room-panel panel"><div class="map-room-heading"><h2>上課教室</h2><span class="pill" id="map-room-count"></span></div><label class="search-field compact">${icon('search')}<input id="room-search" type="search" aria-label="搜尋教室或館舍" placeholder="搜尋教室、館舍或課程" value="${esc(mapQuery)}"></label><div id="room-list" class="room-list"></div></aside><section id="map-detail" class="panel map-detail"></section></div>`;
campusMap=makeMap($('#campus-map'));$$('[data-map-scope]').forEach(b=>b.onclick=()=>{mapScope=b.dataset.mapScope;mapQuery='';mapRoom=null;render();});$('#room-search').oninput=e=>{mapQuery=e.target.value;updateMapRooms();};$('#fit-map').onclick=fitCampusMap;$('#locate-me').onclick=locateMe;updateMapRooms();}
function fitCampusMap(){if(!campusMap)return;const rooms=filteredMapRooms().filter(r=>Number.isFinite(r.lat)&&Number.isFinite(r.lng));if(rooms.length)campusMap.fitBounds(rooms.map(r=>[r.lat,r.lng]),{padding:[45,45],maxZoom:17});else campusMap.setView([22.9985,120.2197],16);}
function updateMapRooms(){const rooms=filteredMapRooms();$('#map-room-count').textContent=rooms.length+' 間';if(!rooms.some(r=>r.key===mapRoom))mapRoom=rooms.find(r=>r.key==='37:75301')?.key??rooms[0]?.key??null;$('#room-list').innerHTML=rooms.map(r=>`<button class="room-list-item ${r.key===mapRoom?'active':''}" data-select-room="${esc(r.key)}" aria-pressed="${r.key===mapRoom}"><span class="room-list-icon">${icon('pin')}</span><span><strong>${esc(r.label)}</strong><small>${esc(r.floor||'樓層未提供')} · ${r.lat?'可導航至館舍':'位置待確認'}</small></span></button>`).join('')||`<div class="empty"><h3>${mapQuery?'找不到這間教室':'還沒有上課地點'}</h3><p>${mapQuery?'換個教室編號或館舍名稱試試。':'先加入課程，或切換「全部教室」。'}</p>${mapQuery?'':'<a href="#courses" class="button secondary">探索課程</a>'}</div>`;$$('[data-select-room]').forEach(b=>b.onclick=()=>selectMapRoom(b.dataset.selectRoom));if(campusMap){mapMarkers.forEach(m=>m.remove());mapMarkers=[];const buildings=new Map();rooms.filter(r=>r.lat).forEach(r=>{if(!buildings.has(r.bid))buildings.set(r.bid,[]);buildings.get(r.bid).push(r);});let i=1;for(const group of buildings.values()){const r=group.find(r=>r.key===mapRoom)??group[0];const m=marker(campusMap,r,i++,group.some(r=>r.key===mapRoom));m.bindTooltip(esc(r.building.replace(/^\w+\s+/,'')),{direction:'top',offset:[0,-10]});m.on('click',()=>selectMapRoom(r.key));m.room=r;mapMarkers.push(m);}fitCampusMap();}renderMapDetail();}
function selectMapRoom(key){mapRoom=key;$$('[data-select-room]').forEach(b=>{b.classList.toggle('active',b.dataset.selectRoom===key);b.setAttribute('aria-pressed',String(b.dataset.selectRoom===key));});const r=data.rooms[key];mapMarkers.forEach((m,i)=>m.setIcon(L.divIcon({className:'campus-pin'+(m.room?.bid===r?.bid?' active':''),html:String(i+1),iconSize:[27,27],iconAnchor:[13,13]})));if(r?.lat&&campusMap)campusMap.setView([r.lat,r.lng],18,{animate:!matchMedia('(prefers-reduced-motion:reduce)').matches});renderMapDetail();}
function renderMapDetail(){const r=data.rooms[mapRoom];if(!r){$('#map-detail').innerHTML='<div class="empty"><p>選擇教室後，這裡會顯示樓層與導航。</p></div>';return;}const courses=selected().filter(c=>courseSessions(c,state.tutorials).some(s=>s.room?.key===r.key));$('#map-detail').innerHTML=`<div class="map-detail-main"><span class="eyebrow">YOUR DESTINATION</span><h2>${esc(r.label)}</h2><p class="muted">${r.floor?`<span class="floor-badge">${esc(r.floor)}</span>`:''}${esc(r.building?.replace(/^\w+\s+/,'')||'館舍資料待確認')}</p>${courses.length?`<div class="room-course-tags">${courses.map(c=>`<button data-detail="${c.id}" class="pill">${esc(c.name)}</button>`).join('')}</div>`:'<p class="small muted">這間教室目前沒有加入你的課表。</p>'}</div><div class="map-detail-actions">${roomButtons(r)}<p class="small muted">Google Maps 導航至館舍 · 成大教室圖查看${r.floor?'樓層與室內位置':'官方位置'}</p></div>`;bindDetails();}
let locationMarker=null;
function locateMe(){if(!navigator.geolocation){toast('這個瀏覽器無法提供定位，請直接使用步行導航。');return;}const button=$('#locate-me');button.disabled=true;button.textContent='定位中…';navigator.geolocation.getCurrentPosition(position=>{if(view==='map'&&campusMap){locationMarker?.remove();locationMarker=L.circleMarker([position.coords.latitude,position.coords.longitude],{radius:8,color:'#fff',weight:3,fillColor:'#286bec',fillOpacity:1}).addTo(campusMap).bindTooltip('你的位置');campusMap.setView([position.coords.latitude,position.coords.longitude],16);toast('已顯示目前位置');}button.disabled=false;button.innerHTML=icon('locate')+'我的位置';},()=>{button.disabled=false;button.innerHTML=icon('locate')+'我的位置';toast('無法取得位置。請允許定位，或直接使用 Google Maps 步行導航。');},{enableHighAccuracy:true,timeout:12000,maximumAge:60000});}
async function init(){try{const response=await fetch('./data.json');if(!response.ok)throw Error('data');data=await response.json();byId=new Map(data.courses.map(c=>[c.id,c]));state=loadState();render();registerTools();}catch{$('#main').innerHTML='<div class="error-box"><h2>課程資料暫時無法載入</h2><p>請確認網路連線後重新整理。</p><button class="button" onclick="location.reload()">重新載入</button></div>';}}
$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));$('#about-btn').onclick=()=>$('#info-dialog').showModal();bindClose();$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));$('#reset-demo').onclick=()=>{if(!confirm('將目前勾選的課程還原成示範課表？'))return;state={ids:DEMO.filter(id=>byId.has(id)),tutorials:{},edited:false};save();$('#info-dialog').close();render();toast('已還原示範課表');};window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});init();

function registerTools(){
 const context=document.modelContext;if(!context?.registerTool)return;
 const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});
 const tools=[{name:'read_ncku_timetable',description:'Read the current device-local demonstration timetable and time conflicts. This is not university enrolment.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(){return {semester:data.semester,courses:selected().map(c=>({id:c.id,name:c.name,credits:c.credits,sessions:courseSessions(c,state.tutorials).map(s=>({time:timeLabel(s),room:roomOf(s)?.label??null}))})),conflicts:conflicts(selected(),state.tutorials)};}},{name:'set_ncku_demo_courses',description:'Replace the current browser demonstration timetable with the specified official course IDs. Does not enrol at the university.',inputSchema:{type:'object',properties:{courseIds:{type:'array',items:{type:'string'},maxItems:100,uniqueItems:true}},required:['courseIds'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='courseIds')||!Array.isArray(input.courseIds)||input.courseIds.length>100||input.courseIds.some(id=>typeof id!=='string'||!byId.has(id))||new Set(input.courseIds).size!==input.courseIds.length)throw new Error('Provide unique course IDs from the official catalogue.');state.ids=[...input.courseIds];state.edited=true;save();render();return {selectedCount:state.ids.length,conflicts:conflicts(selected(),state.tutorials)};}}];
 for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch{}}
}
